create table "sb_auth_users" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table "sb_auth_sessions" ("id" text not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" text not null references "sb_auth_users" ("id") on delete cascade);

create table "sb_auth_accounts" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "sb_auth_users" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table "sb_auth_verifications" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table "sb_auth_limits" ("id" text not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);

create index "sb_auth_sessions_userId_idx" on "sb_auth_sessions" ("userId");

create index "sb_auth_accounts_userId_idx" on "sb_auth_accounts" ("userId");

create index "sb_auth_verifications_identifier_idx" on "sb_auth_verifications" ("identifier");
CREATE TABLE sb_admitted_users (
  user_id text PRIMARY KEY REFERENCES sb_auth_users(id) ON DELETE CASCADE,
  active boolean NOT NULL DEFAULT true,
  administrator boolean NOT NULL DEFAULT false
);
CREATE TABLE sb_instance (id integer PRIMARY KEY CHECK (id=1), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sb_invitations (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  token_hash text NOT NULL UNIQUE,
  workspace_id uuid REFERENCES sb_workspaces(id),
  role text NOT NULL CHECK (role IN ('owner','editor','viewer')),
  bootstrap boolean NOT NULL DEFAULT false,
  expires_at timestamptz NOT NULL,
  used_by text REFERENCES sb_auth_users(id),
  used_at timestamptz,
  revoked boolean NOT NULL DEFAULT false,
  CHECK ((used_by IS NULL) = (used_at IS NULL))
);
CREATE INDEX sb_invitations_email ON sb_invitations(email, expires_at);

CREATE TABLE sb_jobs (
 id uuid PRIMARY KEY, project_id uuid NOT NULL, revision integer NOT NULL,
 workspace_id uuid NOT NULL REFERENCES sb_workspaces(id), actor_id text NOT NULL,
 operation_id uuid NOT NULL, request_digest text NOT NULL, input jsonb NOT NULL,
 state text NOT NULL CHECK (state IN ('queued','running','cancelling','completed','partial','cancelled','timed-out','failed')),
 origin text NOT NULL CHECK (origin IN ('computed','imported')),
 report jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(),
 attempt_id uuid, attempts integer NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 2),
 lease_until timestamptz, started_at timestamptz,
 FOREIGN KEY (project_id,revision) REFERENCES sb_revisions(project_id,revision),
 UNIQUE(project_id,actor_id,operation_id)
);
CREATE INDEX sb_jobs_queue ON sb_jobs(state,created_at,id);
CREATE UNIQUE INDEX sb_jobs_active_workspace ON sb_jobs(workspace_id) WHERE state IN ('running','cancelling');
CREATE TABLE sb_job_attempts (
 id uuid PRIMARY KEY, job_id uuid NOT NULL REFERENCES sb_jobs(id),
 input jsonb NOT NULL, digest text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 prepared_at timestamptz, finished_at timestamptz, outcome text
);
CREATE TABLE sb_worker_heartbeats (id text PRIMARY KEY, updated_at timestamptz NOT NULL DEFAULT now());

ALTER TABLE sb_revisions ADD COLUMN operation_kind text NOT NULL DEFAULT 'save' CHECK (operation_kind IN ('create','save','restore'));
ALTER TABLE sb_revisions ADD COLUMN source_revision integer;
ALTER TABLE sb_revisions ADD COLUMN expected_revision integer;
UPDATE sb_revisions SET operation_kind='create' WHERE revision=1;
ALTER TABLE sb_revisions ADD CONSTRAINT sb_revision_restore_source FOREIGN KEY (project_id,source_revision) REFERENCES sb_revisions(project_id,revision);
ALTER TABLE sb_revisions ADD CONSTRAINT sb_revision_restore_shape CHECK (
  (operation_kind='restore' AND source_revision IS NOT NULL AND source_revision>0 AND expected_revision IS NOT NULL AND expected_revision>0 AND source_revision<revision AND expected_revision=revision-1)
  OR (operation_kind<>'restore' AND source_revision IS NULL AND expected_revision IS NULL)
);
